theorem erdos_125 : ∃ n : ℕ, n ∉ setAB := by
  use 62
  intro h
  simp only [setAB, Set.mem_setOf] at h
  obtain ⟨a, ha, b, hb, hab⟩ := h

  -- Bound a and b from hab : a + b = 62
  have a_bound : a ≤ 62 := by omega
  have b_bound : b ≤ 62 := by omega

  -- Key insight: numbers with all base-3 digits ≤ 1 are very sparse
  -- Elements of setA up to 62: {0, 1, 3, 4, 9, 10, 12, 13, 27, 28, 30, 31, 36, 37, 39, 40}
  -- Elements of setB up to 62: {0, 1, 4, 5, 16, 17, 20, 21}

  -- For any element not in these sets, we can derive a contradiction from ha or hb
  interval_cases a
  all_goals (
    -- For most cases, a ∉ setA, so ha is false
    simp only [setA, Set.mem_setOf, Nat.digits] at ha
    try (norm_num [Nat.digits] at ha; exact absurd trivial ha)
    try (interval_cases b;
         all_goals (simp only [setB, Set.mem_setOf, Nat.digits] at hb;
                   try (norm_num [Nat.digits] at hb; exact absurd trivial hb);
                   try (norm_num at hab; omega)))
  )

